#include <pthread.h>
#include <linux/sched.h>

void unregister_ppp_channel(struct ppp_channel *chan) {
    if (!chan) {
        return;
    }

    // Set the PPP pointer to NULL to indicate the channel is unregistered.
    chan->ppp = NULL;

    // Acquire write lock to ensure no ongoing operations.
    pthread_rwlock_wrlock(&chan->lock);

    // Disconnect the channel.
    if (chan->disconnect) {
        chan->disconnect(chan);
    }

    // Remove the channel from the list of all channels.
    list_del(&chan->list);

    // Decrement the reference count of the channel's file structure.
    if (chan->file && chan->file->f_count) {
        atomic_dec(&chan->file->f_count);
        if (atomic_read(&chan->file->f_count) == 0) {
            kfree(chan->file);
        }
    }

    // Wake up any processes waiting on the channel's file.
    wake_up_interruptible(&chan->wait);

    // Release the write lock.
    pthread_rwlock_unlock(&chan->lock);
}
